    string ISimpleLocalizerBase_PropertyPanel.Description_Effect_AdvancedMath1 => Description_Effect_AdvancedMath1;
    /// <summary>
    /// Get the localized string for Description_Effect_AdvancedMath1 in de-DE (like '
    /// Führt die ausgewählte mathematische Funktion für eine Zahl aus und wählt die Überladung basierend auf dem eingegebenen numerischen Typ aus. Trigonometrische Funktionen verwenden Bogenmaß; SinCos gibt sowohl Sinus als auch Cosinus aus.
    /// ')
    /// </summary>
    public static string Description_Effect_AdvancedMath1 => $"Führt die ausgewählte mathematische Funktion für eine Zahl aus und wählt die Überladung basierend auf dem eingegebenen numerischen Typ aus. Trigonometrische Funktionen verwenden Bogenmaß; SinCos gibt sowohl Sinus als auch Cosinus aus.";
    
    string ISimpleLocalizerBase_PropertyPanel.Description_Effect_AdvancedMath2 => Description_Effect_AdvancedMath2;
    /// <summary>
    /// Get the localized string for Description_Effect_AdvancedMath2 in de-DE (like '
    /// Führt eine ausgewählte mathematische Funktion für zwei Zahlen aus. Der Endpunktname ändert sich mit der Funktion; DivRem gibt sowohl den ganzzahligen Quotienten als auch den Rest aus.
    /// ')
    /// </summary>
    public static string Description_Effect_AdvancedMath2 => $"Führt eine ausgewählte mathematische Funktion für zwei Zahlen aus. Der Endpunktname ändert sich mit der Funktion; DivRem gibt sowohl den ganzzahligen Quotienten als auch den Rest aus.";
    
    string ISimpleLocalizerBase_PropertyPanel.Description_Effect_AdvancedMath3 => Description_Effect_AdvancedMath3;
    /// <summary>
    /// Get the localized string for Description_Effect_AdvancedMath3 in de-DE (like '
    /// Führt eine ausgewählte mathematische Funktion für drei Zahlen aus. Clamp begrenzt den Zahlenbereich, FusedMultiplyAdd berechnet Multiplikation und Addition und Round kann die Anzahl der Dezimalstellen und die Rundungsmethode angeben.
    /// ')
    /// </summary>
    public static string Description_Effect_AdvancedMath3 => $"Führt eine ausgewählte mathematische Funktion für drei Zahlen aus. Clamp begrenzt den Zahlenbereich, FusedMultiplyAdd berechnet Multiplikation und Addition und Round kann die Anzahl der Dezimalstellen und die Rundungsmethode angeben.";
    
